<?php
require __DIR__.'/../includes/functions.php';require_login('admin');$total=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$active=(int)db()->query("SELECT COUNT(*) FROM users WHERE role='student' AND is_active=1")->fetchColumn();$complete=(int)db()->query('SELECT COUNT(*) FROM student_profiles WHERE consent=1')->fetchColumn();$urgent=(int)db()->query('SELECT COUNT(*) FROM student_profiles WHERE emergency_flag=1')->fetchColumn();$pending=(int)db()->query("SELECT COUNT(*) FROM student_profiles WHERE case_status IN ('new','in_progress','referred')")->fetchColumn();$grades=db()->query("SELECT COALESCE(p.grade,'بدون پایه') label,COUNT(*) total FROM users u LEFT JOIN student_profiles p ON p.user_id=u.id WHERE u.role='student' GROUP BY p.grade ORDER BY total DESC")->fetchAll();$years=db()->query('SELECT y.title,COUNT(e.id) total FROM academic_years y LEFT JOIN student_enrollments e ON e.academic_year_id=y.id GROUP BY y.id ORDER BY y.title DESC')->fetchAll();layout_start('گزارش‌های مدیریتی');?><div class="page-head"><div><p class="eyebrow">گزارش‌های مدیریتی</p><h1>گزارش وضعیت سامانه</h1></div><a class="button secondary" href="<?=e(url('/admin/index.php'))?>">بازگشت</a></div><div class="stats-grid"><div class="stat-card"><strong><?=$total?></strong><span>کل دانش‌آموزان</span></div><div class="stat-card accent"><strong><?=$active?></strong><span>حساب فعال</span></div><div class="stat-card"><strong><?=$complete?></strong><span>فرم دارای رضایت</span></div><div class="stat-card warning"><strong><?=$urgent?></strong><span>پرچم اضطراری</span></div><div class="stat-card"><strong><?=$pending?></strong><span>پرونده‌های باز</span></div></div><div class="card table-wrap"><h2>توزیع بر اساس پایه</h2><table><tr><th>پایه</th><th>تعداد</th></tr><?php foreach($grades as $r):?><tr><td><?=e($r['label'])?></td><td><?=e($r['total'])?></td></tr><?php endforeach;?></table></div><div class="card table-wrap"><h2>ثبت‌نام بر اساس سال تحصیلی</h2><table><tr><th>سال</th><th>تعداد</th></tr><?php foreach($years as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['total'])?></td></tr><?php endforeach;?></table></div><?php layout_end(); ?>
